/**
 * @suppress
 */
public object FfiConverterTypeArchiveListener: FfiConverter<ArchiveListener, Long> {
    internal val handleMap = UniffiHandleMap<ArchiveListener>()

    override fun lower(value: ArchiveListener): Long {
        if (value is ArchiveListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ArchiveListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ArchiveListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ArchiveListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ArchiveListener) = 8UL

    override fun write(value: ArchiveListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


